import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { cornerScene } from "../../properties/helpers";

/**
 * One-off dump of the OpenCV fixtures' input image (#132).
 *
 * The fixtures are generated by Python from an image that TypeScript produced.
 * Re-implementing `cornerScene`'s RNG in a second language would put a silent
 * divergence at the very bottom of the trust chain, so the image is dumped ONCE
 * from TypeScript, committed, and read as bytes by both sides.
 *
 * It is a binary PGM (P5, maxval 255) rather than a PNG so neither side needs an
 * image-encoder dependency: the file is a 15-byte header and the raw pixels.
 *
 * This is a generator, not a regression test, so it is skipped in every normal
 * run. Re-dump deliberately with:
 *
 *   JSFEAT_DUMP_SCENE=1 npx vitest run tests/fixtures/opencv/dump-scene.test.ts
 *
 * and then regenerate EVERY fixture, because their `meta.sha256` pins the bytes
 * of this file (see README.md).
 */

const WIDTH = 640;
const HEIGHT = 480;
const HEADER = `P5\n${WIDTH} ${HEIGHT}\n255\n`; // 15 bytes
const SCENE_FILE = fileURLToPath(new URL("./scene-640x480.pgm", import.meta.url));

describe("OpenCV fixture input image", () => {
    it.skipIf(process.env.JSFEAT_DUMP_SCENE !== "1")("dumps cornerScene(640, 480) as a binary PGM", () => {
        const scene = cornerScene(WIDTH, HEIGHT);
        writeFileSync(SCENE_FILE, Buffer.concat([Buffer.from(HEADER, "ascii"), Buffer.from(scene.data)]));

        // Re-read what actually landed on disk, so a short write or a wrong
        // header cannot pass silently (and so this test asserts when it runs).
        const written = readFileSync(SCENE_FILE);
        expect(written.length).toBe(15 + WIDTH * HEIGHT); // 307215
        expect(written.subarray(0, 15).toString("ascii")).toBe("P5\n640 480\n255\n");
        expect(Array.from(written.subarray(15))).toEqual(Array.from(scene.data));
    });
});
